function publicState(){return{mode:S.mode,phase:S.phase,activeSeconds:Math.round(S.elapsed),time:gameTime(),position:{x:+(S.mode==='walk'?S.playerX:S.boatX).toFixed(1),z:+(S.mode==='walk'?S.playerZ:S.boatZ).toFixed(1)},packed:S.packed,loaded:S.loaded,moored:S.moored,engine:S.engine,anchor:S.anchor,speedKnots:+(S.speed*1.94384).toFixed(1),fuel:Math.round(S.fuel),waypoint:S.waypoint?.name||null,fishState:S.fishState,tension:Math.round(S.tension),stamina:Math.round(S.stamina),lineDistance:+S.lineDistance.toFixed(1),casts:S.casts,catches:S.catches.map(f=>({name:f.name,length:f.length,kept:f.kept})),breaks:S.breaks,misses:S.misses,sailedMeters:Math.round(S.sailed),walkedMeters:Math.round(S.walked),fps,paused:S.paused,interaction:nearMessage,renderErrors,tripComplete:S.tripComplete};}
function drawMap(ctx,w,h,large){ctx.clearRect(0,0,w,h);ctx.fillStyle='#173843';ctx.fillRect(0,0,w,h);const scale=large?.67:.39;const cx=w/2,cz=large?75:45;const map=(x,z)=>[cx+x*scale,cz+(-z-65)*scale];ctx.strokeStyle='#94b5ad18';ctx.lineWidth=1;for(let x=0;x<w;x+=24){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=0;y<h;y+=24){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}ctx.fillStyle='#57716a';ctx.fillRect(0,0,w,cz-50*scale);let p0=map(-4,85),p1=map(4,-86);ctx.fillStyle='#b8ae8e';ctx.fillRect(p0[0],p0[1],8*scale,p1[1]-p0[1]);let dock=map(9,-76);ctx.fillRect(dock[0]-3*scale,dock[1]-3,10*scale,4);ctx.font=`${large?11:9}px sans-serif`;ctx.textAlign='center';for(let i=0;i<FISHING_SPOTS.length;i++){let sp=FISHING_SPOTS[i],p=map(sp.x,sp.z);ctx.strokeStyle='#d8d2a875';ctx.setLineDash([3,4]);ctx.beginPath();ctx.arc(p[0],p[1],large?22:12,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#d3c795';ctx.beginPath();ctx.arc(p[0],p[1],3,0,Math.PI*2);ctx.fill();if(large){ctx.fillStyle='#d2ddd0';ctx.fillText(sp.name,p[0],p[1]+36);}}
 const me=map(S.mode==='walk'?S.playerX:S.boatX,S.mode==='walk'?S.playerZ:S.boatZ);if(S.waypoint){let p=map(S.waypoint.x,S.waypoint.z);ctx.strokeStyle='#d3bc83aa';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(...me);ctx.lineTo(...p);ctx.stroke();ctx.setLineDash([]);}ctx.save();ctx.translate(...me);ctx.rotate(S.mode==='walk'?-S.yaw:-S.heading);ctx.fillStyle='#f3d79a';ctx.beginPath();ctx.moveTo(0,7);ctx.lineTo(-4,-5);ctx.lineTo(0,-2);ctx.lineTo(4,-5);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#a6beb7';ctx.font='9px monospace';ctx.textAlign='left';ctx.fillText('N',w-17,14);ctx.fillText(large?'0         100 m':'100 m',9,h-9);ctx.fillRect(9,h-18,100*scale,1);}

let prev=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-prev)/1000,.05);prev=now;S.time+=dt;frameCount++;frameT+=dt;if(frameT>=1){fps=Math.round(frameCount/frameT);frameCount=0;frameT=0;}let walking=false;if(S.mode!=='intro'&&!S.paused){S.elapsed+=dt;if(S.mode==='walk')walking=updateWalking(dt);else updateBoat(dt);updateFishing(dt);dirtySave+=dt;if(dirtySave>12){save();dirtySave=0;}}boat.position.set(S.boatX,waveHeight(S.boatX,S.boatZ,S.time),S.boatZ);boat.rotation.set(Math.sin(S.time*.63)*.02*S.motion,S.heading,Math.sin(S.time*.87)*.026*S.motion*(S.weather==='breeze'?1.8:1));if(boat.userData.propeller&&S.engine)boat.userData.propeller.rotation.z+=dt*30*(.3+S.throttle);fisher.visible=S.mode==='boat'&&S.view==='third';world.update(S.time,dt,boat,S.speed,S.quality);updateCamera(dt,walking);updateRod();updateRopes();if(splashLife>0){splashLife-=dt*.65;splash.material.opacity=Math.max(0,splashLife*.45);splash.scale.setScalar(1+(1-splashLife)*6);splash.position.y=waveHeight(splash.position.x,splash.position.z,S.time)+.05;}audio.update(S.time,S.engine,S.throttle,walking);renderer.render(scene,camera);if(S.time-lastUI>.18){lastUI=S.time;updateUI();}}
