const mcp=document.modelContext;if(mcp?.registerTool){const ctl=new AbortController();const reg=tool=>{try{Promise.resolve(mcp.registerTool(tool,{signal:ctl.signal})).catch(()=>{});}catch{}};reg({name:'read_fishing_game_state',title:'读取海钓游戏状态',description:'Read the current simulated trip, fish fight, vessel and equipment state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>publicState()});reg({name:'start_fishing_trip',title:'开始海钓航程',description:'Start a new trip at the wharf through the same action as the start button.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(S.mode!=='intro')throw Error('Trip already started');start();return publicState();}});reg({name:'set_fishing_waypoint',title:'设置辅助航向',description:'Select a marked fishing spot or return wharf. Requires boarding, unmooring, retrieving line and lifting anchor.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['kelp','sand','reef','dock']}},required:['destination'],additionalProperties:false},execute:({destination})=>{const allowed=['kelp','sand','reef','dock'];if(!allowed.includes(destination))throw Error('Unknown destination');if(S.mode!=='boat'||S.moored||S.anchor||S.fishState!=='idle')throw Error('Boat is not ready to navigate');setWaypoint(destination==='dock'?'dock':String(allowed.indexOf(destination)));updateUI();return publicState();}});window.addEventListener('pagehide',()=>ctl.abort(),{once:true});}
